create extension if not exists pgcrypto;
create table if not exists customers(id uuid primary key default gen_random_uuid(),name text,business_name text,email text,phone text,segment text,status text default 'active',intent_score integer default 0,created_at timestamptz default now());
create table if not exists products(id uuid primary key default gen_random_uuid(),name text not null,origin text,roast_level text,cost_price numeric,sale_price numeric,active boolean default true,created_at timestamptz default now());
create table if not exists orders(id uuid primary key default gen_random_uuid(),customer_id uuid references customers(id),total_amount numeric,total_kg numeric,status text default 'pending',created_at timestamptz default now());
create table if not exists behavior_events(id bigint generated always as identity primary key,customer_id uuid references customers(id),anonymous_id text,event_name text not null,page text,object_type text,object_id text,metadata jsonb default '{}'::jsonb,created_at timestamptz default now());
create table if not exists market_signals(id bigint generated always as identity primary key,source text,category text,title text,confidence numeric,metadata jsonb default '{}'::jsonb,detected_at timestamptz default now());
create table if not exists ai_runs(id bigint generated always as identity primary key,agent_name text not null,input_ref jsonb default '{}'::jsonb,output jsonb default '{}'::jsonb,status text default 'completed',created_at timestamptz default now());
create table if not exists ai_insights(id bigint generated always as identity primary key,agent_name text,title text,insight text,evidence jsonb default '{}'::jsonb,confidence numeric,requires_approval boolean default true,status text default 'pending',created_at timestamptz default now());
create table if not exists workflows(id bigint generated always as identity primary key,name text not null,trigger_type text,action_type text,enabled boolean default false,config jsonb default '{}'::jsonb,created_at timestamptz default now());
create index if not exists behavior_events_event_idx on behavior_events(event_name);create index if not exists behavior_events_created_idx on behavior_events(created_at);create index if not exists orders_customer_idx on orders(customer_id);
